create table if not exists detalle_orden (cantidad integer not null check (cantidad>=1), precio_unitario numeric(12,2) not null, autorizado_anulacion_por_id bigint, id bigint generated by default as identity, orden_id bigint, producto_id bigint not null, estado_item varchar(20) not null check (estado_item in ('PENDIENTE','EN_COCINA','LISTO','ENTREGADO','ANULADO')), observaciones varchar(255), primary key (id));
create table if not exists mesa (capacidad integer not null check (capacidad>=1), id bigint generated by default as identity, version bigint, estado varchar(20) not null check (estado in ('DISPONIBLE','OCUPADA','POR_COBRAR')), numero varchar(20) not null unique, zona varchar(20) not null check (zona in ('SALON','TERRAZA','BARRA')), primary key (id));
create table if not exists orden (impoconsumo numeric(12,2) not null, propina numeric(12,2) not null, subtotal numeric(12,2) not null, total numeric(12,2) not null, created_at timestamp(6) not null, id bigint generated by default as identity, mesa_id bigint, mesero_id bigint, version bigint, canal varchar(20) not null check (canal in ('MESA','RAPPI','UBER_EATS','DIDI_FOOD','MOSTRADOR')), estado varchar(20) not null check (estado in ('ABIERTA','EN_PREPARACION','LISTA','PAGADA','ANULADA')), numero_orden varchar(40) unique, codigo_externo_delivery varchar(60), primary key (id));
create table if not exists producto (disponible boolean not null, precio numeric(12,2) not null, stock_actual integer not null check (stock_actual>=0), stock_minimo integer not null check (stock_minimo>=0), id bigint generated by default as identity, version bigint, categoria varchar(30) not null check (categoria in ('PLATO_FUERTE','ENTRADA','BEBIDA','COCTEL','POSTRE')), codigo varchar(40) unique, nombre varchar(120) not null, descripcion varchar(255), imagen_url varchar(255), primary key (id));
create table if not exists ticket_venta (cambio_devuelto numeric(12,2), monto_recibido numeric(12,2) not null, fecha_emision timestamp(6), id bigint generated by default as identity, orden_id bigint not null unique, turno_caja_id bigint, metodo_pago varchar(20) not null check (metodo_pago in ('EFECTIVO','TARJETA','TRANSFERENCIA')), consecutivo varchar(40) not null unique, cliente_nombre varchar(120), primary key (id));
create table if not exists turno_caja (base_inicial numeric(12,2) not null, efectivo_cierre_declarado numeric(12,2), total_ventas_digital numeric(12,2) not null, total_ventas_efectivo numeric(12,2) not null, cajero_id bigint not null, fecha_apertura timestamp(6) not null, fecha_cierre timestamp(6), id bigint generated by default as identity, version bigint, estado varchar(20) not null check (estado in ('ABIERTO','CERRADO')), primary key (id));
create table if not exists usuario (activo boolean not null, id bigint generated by default as identity, rol varchar(20) not null check (rol in ('ADMIN','MESERO','COCINERO_BARMAN','CAJERO','SUPERVISOR')), username varchar(60) not null unique, nombre varchar(120) not null, password varchar(255) not null, primary key (id));
